/* ============================================================
 * Turnario D — VVF Napoli Sommozzatori  |  Service Worker v5
 * Icone VVF incorporate direttamente (nessun file PNG esterno)
 * ============================================================ */

const CACHE = 'turnario-v5';
const BASE = '/turnario-Smzt-D';

// Asset da cachare (SENZA le icone — le serviamo inline qui sotto)
const ASSETS = [
  BASE + '/',
  BASE + '/index.html',
  BASE + '/manifest.json'
];

// Icona VVF Sommozzatori 192×192 su sfondo rosso #c0111f
const ICON_B64 = '';

/* Converte base64 → ArrayBuffer */
function b64ToBuffer(b64) {
  const str = atob(b64);
  const buf = new ArrayBuffer(str.length);
  const view = new Uint8Array(buf);
  for (let i = 0; i < str.length; i++) view[i] = str.charCodeAt(i);
  return buf;
}

/* Crea una Response PNG dall'icona inline */
function iconResponse() {
  return new Response(b64ToBuffer(ICON_B64), {
    status: 200,
    headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=31536000' }
  });
}

/* ─── INSTALL: cacha gli asset di testo + le icone inline ─── */
self.addEventListener('install', e => {
  e.waitUntil(
    caches.open(CACHE).then(async cache => {
      await cache.addAll(ASSETS);
      // Aggiunge le icone direttamente dalla base64 incorporata
      await cache.put(BASE + '/icon-192.png', iconResponse());
      await cache.put(BASE + '/icon-512.png', iconResponse()); // stessa img, accettata da Chrome
    }).then(() => self.skipWaiting())
  );
});

/* ─── ACTIVATE: rimuove cache vecchie ─── */
self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
      .then(() => clients.claim())
  );
});

/* ─── FETCH: cache-first; icone sempre servite inline ─── */
self.addEventListener('fetch', e => {
  // Ignora le chiamate Firebase/Firestore
  const url = e.request.url;
  if (url.includes('firebaseio') || url.includes('firebaseapp') ||
      url.includes('googleapis') || url.includes('firebase')) return;

  // Icone: sempre dalla cache inline (mai dalla rete, che dà 403)
  if (url.includes('/icon-192.png') || url.includes('/icon-512.png')) {
    e.respondWith(iconResponse());
    return;
  }

  // Tutto il resto: cache-first con fallback rete
  e.respondWith(
    caches.match(e.request).then(cached => cached || fetch(e.request))
  );
});
